import React, { useState, useEffect } from 'react';
import { getPendingPayments, confirmPayment, getOrderById } from '../services/api';
import OrderVerificationModal from './OrderVerificationModal';
import { useTheme } from '../context/ThemeContext';

const PaymentConfirmation = () => {
  const { isDarkMode } = useTheme();
  const [pendingPayments, setPendingPayments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [confirming, setConfirming] = useState({});
  const [formData, setFormData] = useState({});
  const [verificationModal, setVerificationModal] = useState({
    isOpen: false,
    orderId: null,
    paymentMethod: null,
    amount: null
  });

  useEffect(() => {
    fetchPendingPayments();
    const interval = setInterval(fetchPendingPayments, 30000); // Refresh every 30 seconds
    return () => clearInterval(interval);
  }, []);

  const fetchPendingPayments = async () => {
    try {
      setLoading(true);
      const res = await getPendingPayments();
      console.log('🔍 Pending payments response:', res.data);
      setPendingPayments(res.data.pendingPayments || []);
    } catch (error) {
      console.error('Error fetching pending payments:', error);
      // Try debug endpoint
      try {
        const debugRes = await fetch('/api/payment/debug');
        const debugData = await debugRes.json();
        console.log('🐛 Debug info:', debugData);
      } catch (debugError) {
        console.error('Debug endpoint failed:', debugError);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleQuickVerify = async (orderId, amount, paymentMethod) => {
    // Open verification modal instead of direct action
    setVerificationModal({
      isOpen: true,
      orderId,
      paymentMethod,
      amount
    });
  };

  const handleVerificationConfirm = async (orderId, paymentMethod) => {
    try {
      setConfirming(prev => ({ ...prev, [orderId]: true }));

      let endpoint, action;
      if (paymentMethod === 'cod') {
        // For COD orders - confirm order
        endpoint = `/api/payment/confirm-order/${orderId}`;
        action = 'confirm';
      } else {
        // For online payments - verify payment
        endpoint = `/api/payment/quick-verify/${orderId}`;
        action = 'verify';
      }

      const token = localStorage.getItem('token');
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          verifiedBy: 'admin'
        })
      });

      if (!response.ok) {
        console.error('🔍 API Response Error:', response.status, response.statusText);
        const errorData = await response.json().catch(() => ({}));
        console.error('🔍 Error Data:', errorData);
        throw new Error(`API Error: ${response.status}`);
      }

      const result = await response.json();
      console.log(`🚀 Quick ${action} completed:`, result);

      // Remove from pending list
      setPendingPayments(prev => prev.filter(p => p.orderId !== orderId));

      const message = paymentMethod === 'cod' 
        ? `✅ Order confirmed and placed automatically for ${orderId}!\nAmount: ₹${verificationModal.amount}\nUser will receive order confirmation.`
        : `✅ Payment verified and Order placed automatically for ${orderId}!\nAmount: ₹${verificationModal.amount}\nUser will receive success notification.`;

      alert(message);
    } catch (error) {
      console.error(`Error in quick ${paymentMethod === 'cod' ? 'confirmation' : 'verification'}:`, error);
      alert(`Failed to ${paymentMethod === 'cod' ? 'confirm order' : 'verify payment'}`);
    } finally {
      setConfirming(prev => ({ ...prev, [orderId]: false }));
    }
  };

  const closeVerificationModal = () => {
    setVerificationModal({
      isOpen: false,
      orderId: null,
      paymentMethod: null,
      amount: null
    });
  };

  const handleConfirmPayment = async (orderId, amount) => {
    try {
      setConfirming(prev => ({ ...prev, [orderId]: true }));

      const data = formData[orderId] || {};
      await confirmPayment(orderId, amount, data.transactionId, data.notes);

      // Remove from pending list
      setPendingPayments(prev => prev.filter(p => p.orderId !== orderId));

      alert(`Payment confirmed for order ${orderId}`);
    } catch (error) {
      console.error('Error confirming payment:', error);
      alert('Failed to confirm payment');
    } finally {
      setConfirming(prev => ({ ...prev, [orderId]: false }));
    }
  };

  const handleSimulatePayment = async (orderId, amount) => {
    try {
      setConfirming(prev => ({ ...prev, [orderId]: true }));

      const token = localStorage.getItem('token');
      const response = await fetch(`/api/payment/simulate-payment/${orderId}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          amount: amount,
          transactionId: 'UPI_SIM_' + Date.now()
        })
      });

      const result = await response.json();
      console.log('💰 Payment simulated:', result);

      // Remove from pending list
      setPendingPayments(prev => prev.filter(p => p.orderId !== orderId));

      alert(`✅ Payment simulated for order ${orderId} - User will see success notification!`);
    } catch (error) {
      console.error('Error simulating payment:', error);
      alert('Failed to simulate payment');
    } finally {
      setConfirming(prev => ({ ...prev, [orderId]: false }));
    }
  };

  const handleInputChange = (orderId, field, value) => {
    setFormData(prev => ({
      ...prev,
      [orderId]: {
        ...prev[orderId],
        [field]: value
      }
    }));
  };

  const formatTime = (timestamp) => {
    return new Date(timestamp).toLocaleString();
  };

  const createTestPayment = async () => {
    try {
      const testOrderId = 'test_' + Date.now();
      const testAmount = 299;
      const endpoint = '/api/payment/test';
      const token = localStorage.getItem('token');
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          orderId: testOrderId,
          amount: testAmount,
          transactionId: formData[testOrderId]?.transactionId,
          notes: formData[testOrderId]?.notes
        })
      });

      const result = await response.json();
      console.log('🧪 Test payment created:', result);

      // Refresh the list
      fetchPendingPayments();
    } catch (error) {
      console.error('Error creating test payment:', error);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center py-12">
        <div className="relative">
          <div className="w-16 h-16 border-4 border-red-200 border-t-red-600 rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-8 h-8 bg-gradient-to-br from-red-500 to-orange-500 rounded-full animate-pulse"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`rounded-3xl border-2 ${isDarkMode ? 'border-white/10 bg-gray-800/50' : 'border-gray-200 bg-white/70'} backdrop-blur-xl shadow-xl p-8`}>
      <div className="flex items-center gap-3 mb-8">
        <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-red-500 to-orange-500 flex items-center justify-center shadow-lg">
          <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z" />
          </svg>
        </div>
        <div>
          <h2 className={`text-2xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
            Pending Orders & Payments Confirmation
          </h2>
          <p className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>
            Manage and confirm pending payment transactions
          </p>
        </div>
      </div>

      {pendingPayments.length === 0 ? (
        <div className={`text-center py-16 rounded-2xl ${isDarkMode ? 'bg-gray-900/30' : 'bg-gray-50/80'} backdrop-blur-sm border-2 ${isDarkMode ? 'border-white/5' : 'border-gray-200'}`}>
          <div className="w-24 h-24 mx-auto mb-6 rounded-3xl bg-gradient-to-br from-red-100 to-orange-100 dark:from-red-900/30 dark:to-orange-900/30 flex items-center justify-center">
            <svg className="w-12 h-12 text-red-500 dark:text-red-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z" />
            </svg>
          </div>
          <h3 className={`text-xl font-bold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
            No Pending Payments
          </h3>
          <p className={`mb-6 ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>
            No pending orders or payments to confirm at the moment
          </p>
          <button
            onClick={createTestPayment}
            className="px-6 py-3 bg-gradient-to-r from-red-500 to-orange-500 text-white rounded-xl font-medium hover:from-red-600 hover:to-orange-600 transform hover:scale-[1.02] transition-all duration-200 shadow-lg hover:shadow-xl hover:shadow-red-500/30 flex items-center gap-2 mx-auto"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
            </svg>
            Create Test Payment
          </button>
        </div>
      ) : (
        <div className="space-y-4">
          {pendingPayments.map((payment) => (
            <div key={payment.orderId} id={`payment-${payment.orderId}`} className="border border-gray-200 rounded-lg p-4 transition-all duration-300">
              <div className="flex justify-between items-start mb-3">
                <div>
                  <div className="flex items-center gap-2 mb-2">
                    <h3 className="font-semibold text-gray-800">
                      Order: {payment.orderId}
                    </h3>
                    <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${
                      payment.paymentMethod === 'cod' 
                        ? 'bg-blue-100 text-blue-800' 
                        : 'bg-purple-100 text-purple-800'
                    }`}>
                      {payment.paymentMethod === 'cod' ? '💵 COD' : '💳 Online'}
                    </span>
                  </div>
                  <p className="text-sm text-gray-600">
                    Amount: <span className="font-semibold text-green-600">₹{payment.amount}</span>
                  </p>
                  <p className="text-xs text-gray-500">
                    Time: {formatTime(payment.timestamp)}
                  </p>
                  {payment.paymentMethod === 'online' && (
                    <p className="text-xs text-gray-500">
                      Verification attempts: {payment.attempts}
                    </p>
                  )}
                </div>
                <div className="text-right">
                  <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${
                    payment.status === 'pending_confirmation' 
                      ? 'bg-orange-100 text-orange-800' 
                      : 'bg-yellow-100 text-yellow-800'
                  }`}>
                    {payment.status === 'pending_confirmation' ? 'Confirmation Pending' : 'Payment Pending'}
                  </span>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3 mb-3">
                <div>
                  <label className="block text-xs font-medium text-gray-700 mb-1">
                    Transaction ID (optional)
                  </label>
                  <input
                    type="text"
                    value={formData[payment.orderId]?.transactionId || ''}
                    onChange={(e) => handleInputChange(payment.orderId, 'transactionId', e.target.value)}
                    className="input text-sm py-1 px-2"
                    placeholder="Enter transaction ID"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-gray-700 mb-1">
                    Notes (optional)
                  </label>
                  <input
                    type="text"
                    value={formData[payment.orderId]?.notes || ''}
                    onChange={(e) => handleInputChange(payment.orderId, 'notes', e.target.value)}
                    className="input text-sm py-1 px-2"
                    placeholder="Add notes"
                  />
                </div>
              </div>

              <div className="flex gap-2">
                <button
                  onClick={() => handleQuickVerify(payment.orderId, payment.amount, payment.paymentMethod)}
                  disabled={confirming[payment.orderId]}
                  className="btn btn-green text-sm py-1 px-3 disabled:opacity-50 font-bold"
                >
                  {confirming[payment.orderId] 
                    ? (payment.paymentMethod === 'cod' ? 'Confirming...' : 'Verifying...') 
                    : (payment.paymentMethod === 'cod' ? '🚀 Quick Confirm & Place Order' : '🚀 Quick Verify & Place Order')
                  }
                </button>
                {payment.paymentMethod === 'online' && (
                  <button
                    onClick={() => handleConfirmPayment(payment.orderId, payment.amount)}
                    disabled={confirming[payment.orderId]}
                    className="btn btn-primary text-sm py-1 px-3 disabled:opacity-50"
                  >
                    {confirming[payment.orderId] ? 'Confirming...' : '📋 Detailed Verify'}
                  </button>
                )}
                {payment.paymentMethod === 'online' && (
                  <button
                    onClick={() => handleSimulatePayment(payment.orderId, payment.amount)}
                    disabled={confirming[payment.orderId]}
                    className="btn btn-secondary text-sm py-1 px-3 disabled:opacity-50"
                  >
                    {confirming[payment.orderId] ? 'Simulating...' : '🎯 Test Payment'}
                  </button>
                )}
                {payment.paymentMethod === 'online' && (
                  <button
                    onClick={() => window.open(`tel:*99#`, '_blank')}
                    className="btn btn-outline text-sm py-1 px-3"
                  >
                    📱 Check UPI
                  </button>
                )}
              </div>

              <div className={`mt-3 p-2 rounded text-xs ${
                payment.paymentMethod === 'cod' 
                  ? 'bg-blue-50 text-blue-700' 
                  : 'bg-green-50 text-green-700'
              }`}>
                <strong>🚀 Quick Workflow:</strong> 
                {payment.paymentMethod === 'cod' 
                  ? ' Click "Quick Confirm & Place Order" → Order automatically placed! User gets order confirmation.'
                  : ' Check UPI app → Click "Quick Verify & Place Order" → Order automatically placed! User gets payment notification.'
                }
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="mt-6 flex justify-between items-center">
        <button
          onClick={fetchPendingPayments}
          className="btn btn-secondary text-sm py-1 px-3"
        >
          🔄 Refresh
        </button>
        <div className="text-sm text-gray-500">
          Auto-refresh every 30 seconds
        </div>
      </div>

      {/* Order Verification Modal */}
      <OrderVerificationModal
        isOpen={verificationModal.isOpen}
        onClose={closeVerificationModal}
        orderId={verificationModal.orderId}
        paymentMethod={verificationModal.paymentMethod}
        amount={verificationModal.amount}
        onConfirm={handleVerificationConfirm}
      />
    </div>
  );
};

export default PaymentConfirmation;
